with
quarantined as (
    select
        source_company_id,
        source_fund_id,
        source_name,
        source_lei,
        source_external_id,
        source_sector,
        source_sub_sector,
        source_country,
        source_status,
        source_reported_on,
        source_record_id,
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key,
        violation_00,
        violation_01
    from {{ ref("investment__portfolio_company_vault__checked_pre") }}
),
violations as (
    select
        'source_record_id_not_null' as rule_name,
        source_company_id,
        source_fund_id,
        source_name,
        source_lei,
        source_external_id,
        source_sector,
        source_sub_sector,
        source_country,
        source_status,
        source_reported_on,
        source_record_id,
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key
    from quarantined
    where violation_00

    union all

    select
        'source_name_not_null' as rule_name,
        source_company_id,
        source_fund_id,
        source_name,
        source_lei,
        source_external_id,
        source_sector,
        source_sub_sector,
        source_country,
        source_status,
        source_reported_on,
        source_record_id,
        company_source_system,
        company_identity_key,
        company_normalised_name,
        company_lei,
        company_external_id,
        company_business_key
    from quarantined
    where violation_01
)

select
    rule_name,
    source_company_id,
    source_fund_id,
    source_name,
    source_lei,
    source_external_id,
    source_sector,
    source_sub_sector,
    source_country,
    source_status,
    source_reported_on,
    source_record_id,
    company_source_system,
    company_identity_key,
    company_normalised_name,
    company_lei,
    company_external_id,
